"""User-facing policy messages (Arabic / English). Generated by code, never by the LLM."""
from __future__ import annotations

UNAVAILABLE_LABELS = {
    "findings": ("نتائج البحث", "research findings"),
    "conclusions": ("الاستنتاجات والتوصيات", "conclusions / recommendations"),
    "methodology": ("المنهجية وأدوات البحث والعينة", "methodology, instruments and sample"),
    "statistics": ("الإحصاءات والأرقام", "statistics and figures"),
    "abstract_summary": ("ملخص أو مستخلص البحث", "an abstract or summary of the research"),
    "full_text": ("النص الكامل أو الفصول أو المراجع", "full text, chapters or references"),
    "hypotheses": ("فروض البحث", "research hypotheses"),
}

METADATA_ONLY = {
    "ar": "تحتوي السجلات المتاحة على بيانات ببليوغرافية فقط (العنوان، المشرفون، السنة، التخصص، رقم التصنيف، عدد الصفحات، المقاس).",
    "en": "The available records contain bibliographic metadata only (title, supervisors, year, subject, call number, extent, dimensions).",
}


def _labels(cats: list[str], lang: str) -> str:
    i = 0 if lang == "ar" else 1
    return (" ، " if lang == "ar" else ", ").join(UNAVAILABLE_LABELS[c][i] for c in cats if c in UNAVAILABLE_LABELS)


def content_unavailable(lang: str, cats: list[str]) -> str:
    what = _labels(cats, lang)
    if lang == "ar":
        return (f"لا تحتوي السجلات المتاحة على معلومات كافية للإجابة بشكل موثوق: {what} غير متوفرة في مجموعة البيانات. "
                f"{METADATA_ONLY['ar']} لن أستنتج ذلك من العناوين أو التخصصات أو أسماء المشرفين.")
    return (f"The available records do not contain enough information to answer reliably: {what} is not part of the dataset. "
            f"{METADATA_ONLY['en']} I will not infer it from titles, subjects or supervisor names.")


def no_results(lang: str) -> str:
    return ("لم يتم العثور على معلومات مطابقة في مجموعة البيانات المتاحة." if lang == "ar"
            else "No matching information was found in the available dataset.")


def insufficient(lang: str) -> str:
    return ("لا تحتوي السجلات المتاحة على معلومات كافية للإجابة عن هذا السؤال بشكل موثوق. "
            "السجلات المشابهة (إن وجدت) مذكورة أدناه على أنها غير مؤكدة ولا تُعدّ دليلاً."
            if lang == "ar" else
            "The available records do not contain enough information to answer this question reliably. "
            "Similar records (if any) are listed below as uncertain and are not evidence.")


def record_not_found(lang: str) -> str:
    return ("لم أجد سجلاً بهذا العنوان بالضبط في مجموعة البيانات، لذلك لا يمكنني الإجابة عن بياناته بشكل موثوق. "
            "العناوين المشابهة (إن وجدت) مذكورة أدناه ولا تُعدّ نفس السجل."
            if lang == "ar" else
            "I found no record with exactly this title in the dataset, so I cannot answer about it reliably. "
            "Similar titles (if any) are listed below; they are NOT the same record.")


def withheld(lang: str) -> str:
    return ("تم حجب الإجابة المولَّدة لأنها لم تجتز فحص الأدلة (ادعاءات غير مدعومة بالسجلات). السجلات المسترجعة معروضة أدناه."
            if lang == "ar" else
            "The generated answer was withheld because it failed evidence verification (claims not supported by the "
            "records). The retrieved records are listed below.")


def topical_listing(lang: str, n: int, capped: bool = False) -> str:
    cnt = f"{n}+" if capped else str(n)
    return (f"عثرت على {cnt} سجل(ات) تتضمن عناوينها أو تخصصاتها مصطلحات سؤالك. هذه قائمة بالسجلات فقط؛ "
            "محتوى هذه الأبحاث غير متوفر في مجموعة البيانات."
            if lang == "ar" else
            f"I found {cnt} record(s) whose titles or subjects contain the terms of your question. This is a list of records "
            "only; the content of these works is not available in the dataset.")


# ---------------------------------------------------------------- structured (deterministic) answers
def empty_question(lang: str) -> str:
    return "الرجاء كتابة سؤال." if lang == "ar" else "Please type a question."


def technical_error(lang: str) -> str:
    return ("حدثت مشكلة تقنية أثناء معالجة السؤال. هذا لا يعني أن المعلومة غير موجودة في مجموعة البيانات؛ "
            "يرجى إعادة المحاولة، وإذا استمرت المشكلة فأبلغ فريق الدعم."
            if lang == "ar" else
            "A technical problem occurred while processing the question. This does NOT mean the information is missing "
            "from the dataset; please try again, and report the problem to the support team if it persists.")


def id_not_found(lang: str, rid: str) -> str:
    return (f"لا يوجد مشروع برقم {rid} في قاعدة البيانات الحالية، ولن أعرض مشروعًا آخر بدلًا منه."
            if lang == "ar" else
            f"There is no project with number {rid} in the current database, and no other project is shown in its place.")


def id_found_but_unavailable(lang: str, rid: str, title: str, cats: list[str]) -> str:
    return (f"المشروع رقم {rid} موجود في قاعدة البيانات: «{title}». " if lang == "ar"
            else f"Project #{rid} exists in the database: \"{title}\". ") + content_unavailable(lang, cats)


def premise_mismatch(lang: str, what: str, claimed: str, actual: str) -> str:
    """The question states a detail about an existing record that the database contradicts. Never silently accepted."""
    w_ar = {"supervisor": "المشرف", "year": "السنة"}.get(what, what)
    rec_ar = "المسجلة" if what == "year" else "المسجل"
    actual = actual or ("غير مسجل" if lang == "ar" else "not recorded")
    return (f"تنبيه: السؤال يذكر {w_ar} «{claimed}»، لكن هذا لا يطابق ما هو مسجل لهذا المشروع ({w_ar} {rec_ar}: {actual}). "
            "الإجابة أعلاه تعتمد على السجل المخزَّن فقط."
            if lang == "ar" else
            f"Note: the question mentions the {what} \"{claimed}\", which does NOT match what is recorded for this project "
            f"(recorded {what}: {actual}). The answer above reflects the stored record only.")
